// Package omnicore is the Go port of the omnisens profile format and
// directional gain engine (firmware/src/omni_core.c, web/js/omni-core.js).
// All three implementations are checked against the vectors generated by
// web/test/gen-vectors.mjs; docs/PROTOCOL.md documents the byte layout.
package omnicore

import (
	"encoding/base64"
	"encoding/binary"
	"errors"
	"math"
	"strings"
)

const (
	ConfigVersion = 1
	ConfigSize    = 63
	MaxPoints     = 16
	GainOne       = 4096
	GainMin       = 410
	GainMax       = 32767
	RotationLimit = 4500
	LabelLen      = 16

	FlagEnabled     = 1 << 0
	FlagLinear      = 1 << 1
	FlagChordToggle = 1 << 2
	flagsKnown      = FlagEnabled | FlagLinear | FlagChordToggle

	defaultSmoothing = 32
	defaultResetMs   = 40
	maxSmoothing     = 4096
	maxResetMs       = 2000

	profilePrefix = "omni1."
)

// Config mirrors omni_config_t.
type Config struct {
	Version         uint8
	Flags           uint8
	NPoints         uint8
	SmoothingCounts uint16
	ResetMs         uint16
	RotationCdeg    int16
	CalibDPI        uint16
	GainsQ12        [MaxPoints]uint16
	Label           string
}

// DefaultConfig is the flat, transparent 8-point profile.
func DefaultConfig() Config {
	c := Config{
		Version:         ConfigVersion,
		Flags:           FlagEnabled | FlagChordToggle,
		NPoints:         8,
		SmoothingCounts: defaultSmoothing,
		ResetMs:         defaultResetMs,
	}
	for i := range c.GainsQ12 {
		c.GainsQ12[i] = GainOne
	}
	return c
}

// Sanitize clamps every field into range exactly like omni_config_sanitize().
func (c *Config) Sanitize() {
	c.Version = ConfigVersion
	c.Flags &= flagsKnown
	if c.NPoints < 1 {
		c.NPoints = 1
	}
	if c.NPoints > MaxPoints {
		c.NPoints = MaxPoints
	}
	if c.SmoothingCounts > maxSmoothing {
		c.SmoothingCounts = maxSmoothing
	}
	if c.ResetMs == 0 {
		c.ResetMs = defaultResetMs
	}
	if c.ResetMs > maxResetMs {
		c.ResetMs = maxResetMs
	}
	if c.RotationCdeg > RotationLimit {
		c.RotationCdeg = RotationLimit
	}
	if c.RotationCdeg < -RotationLimit {
		c.RotationCdeg = -RotationLimit
	}
	for i := range c.GainsQ12 {
		switch {
		case i >= int(c.NPoints):
			c.GainsQ12[i] = GainOne
		case c.GainsQ12[i] < GainMin:
			c.GainsQ12[i] = GainMin
		case c.GainsQ12[i] > GainMax:
			c.GainsQ12[i] = GainMax
		}
	}
	var b strings.Builder
	for _, r := range c.Label {
		if b.Len() >= LabelLen || r == 0 {
			break
		}
		if r < 0x20 || r > 0x7e {
			r = '?'
		}
		b.WriteRune(r)
	}
	c.Label = b.String()
}

// Gains returns the NPoints gains as multipliers (1.0 = unchanged).
func (c Config) Gains() []float64 {
	n := int(c.NPoints)
	if n < 1 {
		n = 1
	}
	if n > MaxPoints {
		n = MaxPoints
	}
	g := make([]float64, n)
	for i := range g {
		g[i] = float64(c.GainsQ12[i]) / GainOne
	}
	return g
}

// Linear reports whether the profile asks for linear interpolation.
func (c Config) Linear() bool { return c.Flags&FlagLinear != 0 }

// Pack returns the 63-byte little-endian layout (sanitized).
func (c Config) Pack() [ConfigSize]byte {
	c.Sanitize()
	var out [ConfigSize]byte
	out[0] = c.Version
	out[1] = c.Flags
	out[2] = c.NPoints
	binary.LittleEndian.PutUint16(out[4:], c.SmoothingCounts)
	binary.LittleEndian.PutUint16(out[6:], c.ResetMs)
	binary.LittleEndian.PutUint16(out[8:], uint16(c.RotationCdeg))
	binary.LittleEndian.PutUint16(out[10:], c.CalibDPI)
	for i, g := range c.GainsQ12 {
		binary.LittleEndian.PutUint16(out[12+2*i:], g)
	}
	copy(out[44:44+LabelLen], c.Label)
	return out
}

// Unpack decodes the 63-byte layout. The result is not sanitized.
func Unpack(b []byte) (Config, error) {
	if len(b) < ConfigSize {
		return Config{}, errors.New("profile is too short")
	}
	if b[0] != ConfigVersion {
		return Config{}, errors.New("profile is from a newer omnisens version")
	}
	c := Config{
		Version:         b[0],
		Flags:           b[1],
		NPoints:         b[2],
		SmoothingCounts: binary.LittleEndian.Uint16(b[4:]),
		ResetMs:         binary.LittleEndian.Uint16(b[6:]),
		RotationCdeg:    int16(binary.LittleEndian.Uint16(b[8:])),
		CalibDPI:        binary.LittleEndian.Uint16(b[10:]),
	}
	for i := range c.GainsQ12 {
		c.GainsQ12[i] = binary.LittleEndian.Uint16(b[12+2*i:])
	}
	label := b[44 : 44+LabelLen]
	if n := strings.IndexByte(string(label), 0); n >= 0 {
		label = label[:n]
	}
	c.Label = string(label)
	return c, nil
}

// EncodeProfileCode returns the shareable "omni1.<base64url>" form.
func EncodeProfileCode(c Config) string {
	b := c.Pack()
	return profilePrefix + base64.RawURLEncoding.EncodeToString(b[:])
}

// DecodeProfileCode parses an "omni1." profile code and sanitizes it.
func DecodeProfileCode(code string) (Config, error) {
	code = strings.TrimSpace(code)
	if !strings.HasPrefix(code, profilePrefix) {
		return Config{}, errors.New(`a profile code starts with "omni1."`)
	}
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(code[len(profilePrefix):], "="))
	if err != nil {
		return Config{}, errors.New("profile code is not valid base64")
	}
	c, err := Unpack(raw)
	if err != nil {
		return Config{}, err
	}
	c.Sanitize()
	return c, nil
}

// ConfigFromGains builds a sanitized profile from float multipliers.
func ConfigFromGains(gains []float64, linear bool) Config {
	c := DefaultConfig()
	c.NPoints = uint8(len(gains))
	for i, g := range gains {
		if i >= MaxPoints {
			break
		}
		q := math.Round(g * GainOne)
		if math.IsNaN(q) {
			q = GainOne
		}
		c.GainsQ12[i] = uint16(math.Max(GainMin, math.Min(GainMax, q)))
	}
	if linear {
		c.Flags |= FlagLinear
	}
	c.Sanitize()
	return c
}
